function bothDiagonalsSum(grid: number[][]): number {
  const n = grid.length;
  let total = 0;
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      if (i === j || i + j === n - 1) total += grid[i][j];
  return total;
}

