function bothDiagonalsSum(grid: number[][]): number {
  const n = grid.length;
  let total = 0;
  for (let i = 0; i < n; i++) total += grid[i][i] + grid[i][n - 1 - i];
  if (n % 2 === 1) total -= grid[n >> 1][n >> 1];
  return total;
}

